<?php require_once __DIR__.'/includes/auth.php';require_login();$title='Dashboard';require __DIR__.'/includes/header.php';$stmt=db()->prepare('SELECT * FROM reservations WHERE user_id=? ORDER BY created_at DESC');$stmt->execute([user()['id']]);$rows=$stmt->fetchAll();$flash=consume_flash();?><section class="page-wrap"><h1>Hola, <?=e(user()['name'])?></h1><?php if($flash):?><p class="<?=$flash[0]?>"><?=e($flash[1])?></p><?php endif;?><a class="button" href="<?=BASE_URL?>/reserva.php">Nueva reserva</a><div class="table-wrap"><h2>Mis reservas</h2><table><tr><th>Fecha</th><th>Cantidad</th><th>Estado</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['delivery_date'])?></td><td><?=e((string)$r['quantity'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></section><?php require __DIR__.'/includes/footer.php';?>
